create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'user' check (role in ('user','admin')), created_at timestamptz not null default now());
create table if not exists public.plans (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, monthly_price numeric(12,2) not null default 0, monthly_credits integer not null default 0, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, plan_id uuid not null references public.plans(id), status text not null default 'active', starts_at timestamptz not null default now(), ends_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.usage_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, event_type text not null, units integer not null default 1 check (units>0), metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.promo_codes (id uuid primary key default gen_random_uuid(), code text unique not null, plan_id uuid references public.plans(id), credits integer not null default 0, duration_days integer not null default 30, max_redemptions integer, redeemed_count integer not null default 0, starts_at timestamptz not null default now(), expires_at timestamptz, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.promo_redemptions (id uuid primary key default gen_random_uuid(), promo_id uuid not null references public.promo_codes(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, redeemed_at timestamptz not null default now(), unique(promo_id,user_id));
insert into public.plans(slug,name,monthly_price,monthly_credits) values ('free','Free',0,100),('starter','Starter',299,1000),('pro','Pro',699,3000) on conflict(slug) do nothing;
alter table public.profiles enable row level security; alter table public.subscriptions enable row level security; alter table public.usage_events enable row level security; alter table public.promo_redemptions enable row level security;
create policy "profile own" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "subscription own" on public.subscriptions for select using (user_id=auth.uid());
create policy "usage own" on public.usage_events for select using (user_id=auth.uid());
create policy "usage insert own" on public.usage_events for insert with check (user_id=auth.uid());
create policy "redemption own" on public.promo_redemptions for select using (user_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
